values
  ('cec24c5f-7dc9-400f-a043-4f0311086dc5', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', null, 'topic'::public.curated_course_node_type, 'Bonding and molecular structure', 'This module establishes bonding and molecular structure as the course''s first working framework. It supplies the language and representations needed before the path advances to resonance and reactivity.', 0),
  ('841bff9a-b8cf-42f7-b571-6f3801bdd5cb', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'cec24c5f-7dc9-400f-a043-4f0311086dc5', 'subtopic'::public.curated_course_node_type, 'Hybridization', 'Hybridization identifies a specific object, distinction, or relationship within bonding and molecular structure. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before orbitals because that next topic assumes this starting point.', 0),
  ('2c3ae5f8-bc22-4451-bfe7-fcb697a33639', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'cec24c5f-7dc9-400f-a043-4f0311086dc5', 'subtopic'::public.curated_course_node_type, 'Orbitals', 'Orbitals identifies a specific object, distinction, or relationship within bonding and molecular structure. Learners need to recognize and use it before combining this module''s ideas in later work. After hybridization, orbitals supplies what is needed to address formal charge.', 1),
  ('3a08981f-4d02-4a75-b181-77647e15710d', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'cec24c5f-7dc9-400f-a043-4f0311086dc5', 'subtopic'::public.curated_course_node_type, 'Formal charge', 'Formal charge identifies a specific object, distinction, or relationship within bonding and molecular structure. Learners need to recognize and use it before combining this module''s ideas in later work. After orbitals, formal charge supplies what is needed to address line structures.', 2),
  ('e3fc859a-386f-4fdc-98fa-d04dcacfaeb3', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'cec24c5f-7dc9-400f-a043-4f0311086dc5', 'subtopic'::public.curated_course_node_type, 'Line structures', 'Line structures identifies a specific object, distinction, or relationship within bonding and molecular structure. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, line structures carries the completed idea into resonance and reactivity.', 3),
  ('bd53db93-2af1-4fdf-b405-e90611817c44', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', null, 'topic'::public.curated_course_node_type, 'Resonance and reactivity', 'This module builds directly on bonding and molecular structure and develops resonance and reactivity. It belongs here because its methods and distinctions are prerequisites for acids and bases.', 1),
  ('710c3d1f-e1d8-4213-bdbc-8f9fb60d3e5e', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'bd53db93-2af1-4fdf-b405-e90611817c44', 'subtopic'::public.curated_course_node_type, 'Electron delocalization', 'Electron delocalization identifies a specific object, distinction, or relationship within resonance and reactivity. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before stability because that next topic assumes this starting point.', 0),
  ('ff2acbda-dce1-4b31-8a6c-3e5789627883', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'bd53db93-2af1-4fdf-b405-e90611817c44', 'subtopic'::public.curated_course_node_type, 'Stability', 'Stability makes the validity limits of resonance and reactivity explicit, showing when an otherwise correct method or system can become unreliable. After electron delocalization, stability supplies what is needed to address curved-arrow discipline.', 1),
  ('82fe22b6-b056-4818-9c00-ceb8126ef586', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'bd53db93-2af1-4fdf-b405-e90611817c44', 'subtopic'::public.curated_course_node_type, 'Curved-arrow discipline', 'Curved-arrow discipline identifies a specific object, distinction, or relationship within resonance and reactivity. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, curved-arrow discipline carries the completed idea into acids and bases.', 2),
  ('9642f6dc-565c-432f-b8fe-68f5ae6cfe95', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', null, 'topic'::public.curated_course_node_type, 'Acids and bases', 'This module builds directly on resonance and reactivity and develops acids and bases. It belongs here because its methods and distinctions are prerequisites for conformations.', 2),
  ('58974032-1fe9-4c36-9f96-23be40c076d3', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '9642f6dc-565c-432f-b8fe-68f5ae6cfe95', 'subtopic'::public.curated_course_node_type, 'PKa', 'PKa identifies a specific object, distinction, or relationship within acids and bases. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before equilibria because that next topic assumes this starting point.', 0),
  ('c6a2a9b2-7de6-4406-a2d0-07af81efdfc3', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '9642f6dc-565c-432f-b8fe-68f5ae6cfe95', 'subtopic'::public.curated_course_node_type, 'Equilibria', 'Equilibria identifies a specific object, distinction, or relationship within acids and bases. Learners need to recognize and use it before combining this module''s ideas in later work. After pka, equilibria supplies what is needed to address inductive/resonance effects.', 1),
  ('55049c1d-34c0-4b33-90ed-df3d718e43d6', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '9642f6dc-565c-432f-b8fe-68f5ae6cfe95', 'subtopic'::public.curated_course_node_type, 'Inductive/resonance effects', 'Inductive/resonance effects identifies a specific object, distinction, or relationship within acids and bases. Learners need to recognize and use it before combining this module''s ideas in later work. After equilibria, inductive/resonance effects supplies what is needed to address solvent.', 2),
  ('fe6d4a12-2556-46d6-8927-c48cb4f7f11e', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '9642f6dc-565c-432f-b8fe-68f5ae6cfe95', 'subtopic'::public.curated_course_node_type, 'Solvent', 'Solvent identifies a specific object, distinction, or relationship within acids and bases. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, solvent carries the completed idea into conformations.', 3),
  ('8513bddc-b7df-4350-bec4-142f87bb819a', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', null, 'topic'::public.curated_course_node_type, 'Conformations', 'This module builds directly on acids and bases and develops conformations. It belongs here because its methods and distinctions are prerequisites for stereochemistry.', 3),
  ('c0df25b7-5f93-4293-bfd3-92c31563581f', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '8513bddc-b7df-4350-bec4-142f87bb819a', 'subtopic'::public.curated_course_node_type, 'Newman projections', 'Newman projections identifies a specific object, distinction, or relationship within conformations. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before cyclohexanes because that next topic assumes this starting point.', 0),
  ('f3ae933e-475e-4456-9d8a-72b0ac65d12b', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '8513bddc-b7df-4350-bec4-142f87bb819a', 'subtopic'::public.curated_course_node_type, 'Cyclohexanes', 'Cyclohexanes identifies a specific object, distinction, or relationship within conformations. Learners need to recognize and use it before combining this module''s ideas in later work. After newman projections, cyclohexanes supplies what is needed to address strain.', 1),
  ('bf3d02d2-ecf6-4057-aba6-d4f0ea5a9c5f', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '8513bddc-b7df-4350-bec4-142f87bb819a', 'subtopic'::public.curated_course_node_type, 'Strain', 'Strain is a governing quantity in conformations, linking local calculations to system-level behavior and offering a consistency check. After cyclohexanes, strain supplies what is needed to address conformational energy.', 2),
  ('0091b702-5f4b-48a3-9660-034ad651d863', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '8513bddc-b7df-4350-bec4-142f87bb819a', 'subtopic'::public.curated_course_node_type, 'Conformational energy', 'Conformational energy is a governing quantity in conformations, linking local calculations to system-level behavior and offering a consistency check. As the final topic in this module, conformational energy carries the completed idea into stereochemistry.', 3),
  ('f7e3c768-044b-4b29-84d4-05f7142cbc36', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', null, 'topic'::public.curated_course_node_type, 'Stereochemistry', 'This module builds directly on conformations and develops stereochemistry. It belongs here because its methods and distinctions are prerequisites for mechanisms and energy.', 4),
  ('531fc7d2-65f5-4b0d-9e5d-66b28c3cc70b', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'f7e3c768-044b-4b29-84d4-05f7142cbc36', 'subtopic'::public.curated_course_node_type, 'Chirality', 'Chirality identifies a specific object, distinction, or relationship within stereochemistry. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before r/s because that next topic assumes this starting point.', 0),
  ('5a1b1385-3f55-4e1a-b22b-5cfd563f17ec', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'f7e3c768-044b-4b29-84d4-05f7142cbc36', 'subtopic'::public.curated_course_node_type, 'R/S', 'R/S identifies a specific object, distinction, or relationship within stereochemistry. Learners need to recognize and use it before combining this module''s ideas in later work. After chirality, r/s supplies what is needed to address enantiomers.', 1),
  ('85538f5f-360d-4fbb-81ad-143115003a42', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'f7e3c768-044b-4b29-84d4-05f7142cbc36', 'subtopic'::public.curated_course_node_type, 'Enantiomers', 'Enantiomers identifies a specific object, distinction, or relationship within stereochemistry. Learners need to recognize and use it before combining this module''s ideas in later work. After r/s, enantiomers supplies what is needed to address diastereomers.', 2),
  ('958fb461-8bae-4102-a414-3fc46cf1318a', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'f7e3c768-044b-4b29-84d4-05f7142cbc36', 'subtopic'::public.curated_course_node_type, 'Diastereomers', 'Diastereomers identifies a specific object, distinction, or relationship within stereochemistry. Learners need to recognize and use it before combining this module''s ideas in later work. After enantiomers, diastereomers supplies what is needed to address optical activity.', 3),
  ('82ea7f80-983b-4ec6-9af4-084f2cb516b3', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'f7e3c768-044b-4b29-84d4-05f7142cbc36', 'subtopic'::public.curated_course_node_type, 'Optical activity', 'Optical activity identifies a specific object, distinction, or relationship within stereochemistry. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, optical activity carries the completed idea into mechanisms and energy.', 4),
  ('92d10753-5a0e-4781-a320-e00892da3a7f', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', null, 'topic'::public.curated_course_node_type, 'Mechanisms and energy', 'This module builds directly on stereochemistry and develops mechanisms and energy. It belongs here because its methods and distinctions are prerequisites for alkyl halides and sn2.', 5),
  ('e259e880-0dc1-4af2-b0d2-92a3398c87b9', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '92d10753-5a0e-4781-a320-e00892da3a7f', 'subtopic'::public.curated_course_node_type, 'Kinetics vs thermodynamics', 'Kinetics vs thermodynamics identifies a specific object, distinction, or relationship within mechanisms and energy. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before intermediates because that next topic assumes this starting point.', 0),
  ('9e3e63ae-ae98-4ee6-9b6b-64c3a62a46ba', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '92d10753-5a0e-4781-a320-e00892da3a7f', 'subtopic'::public.curated_course_node_type, 'Intermediates', 'Intermediates identifies a specific object, distinction, or relationship within mechanisms and energy. Learners need to recognize and use it before combining this module''s ideas in later work. After kinetics vs thermodynamics, intermediates supplies what is needed to address transition states.', 1),
  ('bdcc6e2c-aaa8-4006-9db2-a5fd8064107a', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '92d10753-5a0e-4781-a320-e00892da3a7f', 'subtopic'::public.curated_course_node_type, 'Transition states', 'Transition states identifies a specific object, distinction, or relationship within mechanisms and energy. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, transition states carries the completed idea into alkyl halides and sn2.', 2),
  ('f874feff-4c0b-48c3-9f80-4b0c4ba9441e', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', null, 'topic'::public.curated_course_node_type, 'Alkyl halides and SN2', 'This module builds directly on mechanisms and energy and develops alkyl halides and sn2. It belongs here because its methods and distinctions are prerequisites for sn1 and rearrangements.', 6),
  ('d2bb5082-ae8b-4582-a7fa-24fb54828c76', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'f874feff-4c0b-48c3-9f80-4b0c4ba9441e', 'subtopic'::public.curated_course_node_type, 'Nucleophilicity', 'Nucleophilicity identifies a specific object, distinction, or relationship within alkyl halides and sn2. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before leaving groups because that next topic assumes this starting point.', 0),
  ('d3ac09ad-26a8-4980-b9e4-4835727aa7e6', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'f874feff-4c0b-48c3-9f80-4b0c4ba9441e', 'subtopic'::public.curated_course_node_type, 'Leaving groups', 'Leaving groups identifies a specific object, distinction, or relationship within alkyl halides and sn2. Learners need to recognize and use it before combining this module''s ideas in later work. After nucleophilicity, leaving groups supplies what is needed to address inversion.', 1),
  ('ae37c08e-7e99-4040-b1e0-9bc38a521a08', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'f874feff-4c0b-48c3-9f80-4b0c4ba9441e', 'subtopic'::public.curated_course_node_type, 'Inversion', 'Inversion identifies a specific object, distinction, or relationship within alkyl halides and sn2. Learners need to recognize and use it before combining this module''s ideas in later work. After leaving groups, inversion supplies what is needed to address synthesis.', 2),
  ('5b8790cf-a512-4275-8e55-c88a0f0e8c4f', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'f874feff-4c0b-48c3-9f80-4b0c4ba9441e', 'subtopic'::public.curated_course_node_type, 'Synthesis', 'Synthesis turns the theory of alkyl halides and sn2 into a defensible decision and exposes the relevant structure, cost, or performance trade-offs. As the final topic in this module, synthesis carries the completed idea into sn1 and rearrangements.', 3),
  ('9e3a8aad-2de9-41b0-b3da-c15560e2a74c', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', null, 'topic'::public.curated_course_node_type, 'SN1 and rearrangements', 'This module builds directly on alkyl halides and sn2 and develops sn1 and rearrangements. It belongs here because its methods and distinctions are prerequisites for elimination.', 7),
