  ('0594bd10-ef3c-43cd-a67d-802b3c4db767', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '9e3a8aad-2de9-41b0-b3da-c15560e2a74c', 'subtopic'::public.curated_course_node_type, 'Racemization', 'Racemization identifies a specific object, distinction, or relationship within sn1 and rearrangements. Learners need to recognize and use it before combining this module''s ideas in later work. After solvolysis, racemization supplies what is needed to address competition.', 2),
  ('df1f58c3-2293-46cf-b28a-54a0a8194898', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '9e3a8aad-2de9-41b0-b3da-c15560e2a74c', 'subtopic'::public.curated_course_node_type, 'Competition', 'Competition identifies a specific object, distinction, or relationship within sn1 and rearrangements. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, competition carries the completed idea into elimination.', 3),
  ('6e4617c9-40e6-40f8-aae1-584725835eb6', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', null, 'topic'::public.curated_course_node_type, 'Elimination', 'This module builds directly on sn1 and rearrangements and develops elimination. It belongs here because its methods and distinctions are prerequisites for alkenes.', 8);
