  ('d8330138-10ad-442d-b3ac-122da934f8ea', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '6e4617c9-40e6-40f8-aae1-584725835eb6', 'subtopic'::public.curated_course_node_type, 'Competition maps', 'Competition maps gives elimination a reusable representation for organizing assumptions, variables, and relationships before analysis begins. As the final topic in this module, competition maps carries the completed idea into alkenes.', 3),
