  ('79d60ecd-5b03-486a-9884-d5d30f6125c5', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'f7ec4074-7010-458a-8117-d165773de435', 'subtopic'::public.curated_course_node_type, 'Stability', 'Stability makes the validity limits of alkenes explicit, showing when an otherwise correct method or system can become unreliable. It appears before electrophilic addition because that next topic assumes this starting point.', 0),
  ('68bb5704-25d5-43a1-aeca-ef2cb9bfd91e', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'f7ec4074-7010-458a-8117-d165773de435', 'subtopic'::public.curated_course_node_type, 'Electrophilic addition', 'Electrophilic addition supplies the causal sequence within alkenes, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. After stability, electrophilic addition supplies what is needed to address hydration.', 1),
