  ('a67b1b06-3342-4612-a134-ed320c8054f0', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '027daf00-e3f2-4940-92cb-a65060435345', 'subtopic'::public.curated_course_node_type, 'Additions', 'Additions supplies the causal sequence within alkynes and redox, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. After acidity, additions supplies what is needed to address hydroboration.', 1),
  ('57b4136b-3de6-45c0-baaa-fd44ddd247cf', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '027daf00-e3f2-4940-92cb-a65060435345', 'subtopic'::public.curated_course_node_type, 'Hydroboration', 'Hydroboration identifies a specific object, distinction, or relationship within alkynes and redox. Learners need to recognize and use it before combining this module''s ideas in later work. After additions, hydroboration supplies what is needed to address oxidation/reduction toolkit.', 2),
  ('06bc0d19-0819-4700-a823-90143541041e', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', '027daf00-e3f2-4940-92cb-a65060435345', 'subtopic'::public.curated_course_node_type, 'Oxidation/reduction toolkit', 'Oxidation/reduction toolkit supplies the causal sequence within alkynes and redox, which is necessary for predicting unfamiliar outcomes instead of memorizing examples. As the final topic in this module, oxidation/reduction toolkit carries the completed idea into spectroscopy and synthesis i.', 3),
  ('db154d29-e294-467f-bd12-88f482962f13', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', null, 'topic'::public.curated_course_node_type, 'Spectroscopy and synthesis I', 'This culminating module draws on alkynes and redox and develops spectroscopy and synthesis i. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('216c17a6-4879-4db7-8901-11b79f1a7762', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'db154d29-e294-467f-bd12-88f482962f13', 'subtopic'::public.curated_course_node_type, 'IR', 'IR identifies a specific object, distinction, or relationship within spectroscopy and synthesis i. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before 1h nmr because that next topic assumes this starting point.', 0),
  ('e0cafad5-e322-47fa-997a-b92cbd13cc8d', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'db154d29-e294-467f-bd12-88f482962f13', 'subtopic'::public.curated_course_node_type, '1H NMR', '1H NMR identifies a specific object, distinction, or relationship within spectroscopy and synthesis i. Learners need to recognize and use it before combining this module''s ideas in later work. After ir, 1h nmr supplies what is needed to address ms basics.', 1),
  ('32379df2-d954-4ea4-a72d-4825aeadfbd4', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'db154d29-e294-467f-bd12-88f482962f13', 'subtopic'::public.curated_course_node_type, 'MS basics', 'MS basics identifies a specific object, distinction, or relationship within spectroscopy and synthesis i. Learners need to recognize and use it before combining this module''s ideas in later work. After 1h nmr, ms basics supplies what is needed to address short retrosynthetic sequences.', 2),
  ('b3df945f-417a-4029-8baa-f44e65d30e0a', '79badb41-0d8d-44f6-83fa-1e32ea4ae69e', 'db154d29-e294-467f-bd12-88f482962f13', 'subtopic'::public.curated_course_node_type, 'Short retrosynthetic sequences', 'Short retrosynthetic sequences identifies a specific object, distinction, or relationship within spectroscopy and synthesis i. Learners need to recognize and use it before combining this module''s ideas in later work. As the final course topic, short retrosynthetic sequences requires ideas from the complete path to be integrated and transferred.', 3);
